[Serializable] public class SaveData {public int rescuedHeroes=1,rescueVersion,completedStages;public List<FavoriteBuild> favorites=new List<FavoriteBuild>();public int coins,totalKills,wins,bestLevel,curseUnlocks,dragonKills,bossKills,dragonUnlocks,dragonMissionVersion;public int relicOwned;public int[] dragonMastery=new int[3];public int[] relicLoadouts=NewLoadouts();static int[] NewLoadouts(){var a=new int[Catalog.Heroes.Length*2];for(int i=0;i<a.Length;i++)a[i]=-1;return a;}public int[] weaponLoadouts;public void NormalizeWeapons(){if(weaponLoadouts==null||weaponLoadouts.Length!=6){var old=weaponLoadouts;weaponLoadouts=new[]{-1,-1,-1,-1,-1,-1};if(old!=null)Array.Copy(old,weaponLoadouts,Math.Min(old.Length,6));}for(int i=0;i<6;i++)if(weaponLoadouts[i]< -1||weaponLoadouts[i]>8)weaponLoadouts[i]=-1;}public int[] perks=new int[4];public void NormalizeRelics(){NormalizeWeapons();if(relicLoadouts==null||relicLoadouts.Length!=Catalog.Heroes.Length*2){var old=relicLoadouts;relicLoadouts=NewLoadouts();if(old!=null)Array.Copy(old,relicLoadouts,Math.Min(old.Length,relicLoadouts.Length));}for(int i=0;i<relicLoadouts.Length;i++){int id=relicLoadouts[i];if(id<0||id>=8||id%2!=i%2||(relicOwned&(1<<id))==0)relicLoadouts[i]=-1;}}public static SaveData Load(){try{var s=JsonUtility.FromJson<SaveData>(PlayerPrefs.GetString(EditorTestProfile.Key("NSF.Save"),"{}"));if(EditorTestProfile.Enabled&&!PlayerPrefs.HasKey(EditorTestProfile.Key("NSF.Save")))s=EditorTestProfile.CreateSave();if(s==null)s=new SaveData();if(s.perks==null||s.perks.Length!=4)s.perks=new int[4];if(s.rescueVersion<1){if(PlayerPrefs.HasKey(EditorTestProfile.Key("NSF.Save")))s.rescuedHeroes|=57;s.rescueVersion=1;}if(s.favorites==null)s.favorites=new List<FavoriteBuild>();s.completedStages&=15;if(EditorTestProfile.Enabled)s.completedStages=15;s.RefreshDragonMissions();s.NormalizeRelics();return s;}catch{return new SaveData();}}public int RefreshDragonMissions(){int previous=dragonUnlocks;if(dragonMissionVersion<1){dragonKills=Mathf.Max(dragonKills,Mathf.Max(0,totalKills));if(bossKills==0&&(curseUnlocks!=0||wins>0))bossKills=1;dragonMissionVersion=1;}if(dragonKills>=1000)dragonUnlocks|=1;if(bossKills>=1)dragonUnlocks|=2;if(wins>=1)dragonUnlocks|=4;return dragonUnlocks&~previous;}public void Store(){rescueVersion=1;PlayerPrefs.SetString(EditorTestProfile.Key("NSF.Save"),JsonUtility.ToJson(this));PlayerPrefs.Save();}}
